# Extract company names and their employee counts per country
companies = {}
for row in data_rows:
    company = row[0].value
    if company is None:
        continue
    companies[company] = {}
    for col in range(1, 7):  # Columns B to G (country columns)
        country = ws.cell(row=1, column=col + 1).value
        if country is not None:
            employees = row[col].value
            if employees is not None and employees > 0:
                companies[company][country] = employees

# Calculate the number of countries for each company
company_countries = {}
for company, countries in companies.items():
    company_countries[company] = len(countries)

# Write the results to the specified range
for idx, (company, count) in enumerate(company_countries.items()):
    ws.cell(row=12 + idx, column=9, value=count)

