from openpyxl import load_workbook
from datetime import datetime

# Load the workbook
wb = load_workbook('input.xlsx')

# Access the sheets
front_sheet = wb['Front']
data_sheet = wb['Data']

# Identify the header row and first data row in 'Data' sheet
header_row = None
data_rows = []

for row in data_sheet.iter_rows(min_row=1, max_row=data_sheet.max_row):
    if row[0].value == 'Agent Name':
        header_row = row
        break
    if row[0].value is not None:
        data_rows.append(row)

# Extract unique agent names from the 'Data' sheet
agent_names = set()
for row in data_rows:
    if row[0].value and row[0].value != 'Agent Name':
        agent_names.add(row[0].value)

# Create a dictionary to map agent names to their values for each date
agent_date_values = {}

# Process each agent's data
for row in data_rows:
    if row[0].value and row[0].value != 'Agent Name':
        agent_name = row[0].value
        agent_values = {}
        for col in range(1, len(row)):
            date_cell = data_sheet.cell(row=1, column=col + 1).value
            if date_cell:
                date = datetime.strptime(date_cell, "%Y-%m-%d %H:%M:%S").date()
                value = row[col].value
                if value is not None:
                    agent_values[date] = value
        agent_date_values[agent_name] = agent_values

# Write computed values to the 'Front' sheet range B2:C12
for row_idx in range(1, 13):  # Rows 2 to 12 (1-indexed)
    date_cell = front_sheet.cell(row=row_idx + 1, column=2).value
    agent_cell = front_sheet.cell(row=row_idx + 1, column=1).value
    result_cell = front_sheet.cell(row=row_idx + 1, column=3)

    if date_cell and agent_cell:
        date = datetime.strptime(date_cell, "%Y-%m-%d %H:%M:%S").date()
        if agent_cell in agent_date_values and date in agent_date_values[agent_cell]:
            result_cell.value = agent_date_values[agent_cell][date]
        else:
            result_cell.value = None  # Return blank

# Save the workbook
wb.save('output.xlsx')
