from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws_summary = wb['Summary']
ws_sheet1 = wb['Sheet1']

# Identify header and data rows
header_row = None
data_rows = []

# Find header row
for row in ws_summary.iter_rows(min_row=1, max_row=9):
    if any(cell.value for cell in row):
        header_row = row
        break

# Find data rows
for row in ws_summary.iter_rows(min_row=2, max_row=9):
    if any(cell.value for cell in row):
        data_rows.append(row)

# Identify the columns for Name, HD, SD, and Status
name_col = None
hd_col = None
sd_col = None
status_col = None

for idx, cell in enumerate(header_row):
    if cell.value == 'Name':
        name_col = idx
    elif cell.value == 'HD':
        hd_col = idx
    elif cell.value == 'SD':
        sd_col = idx
    elif cell.value == 'Status':
        status_col = idx

# Read the data from Sheet1
sheet1_data = []
for row in ws_sheet1.iter_rows(min_row=2, max_row=28):
    sheet1_data.append({
        'Status': row[0].value,
        'Name': row[1].value,
        'Type': row[2].value,
        'Amt': row[3].value
    })

# Group amounts by Name and Type
summary_data = {}

for entry in sheet1_data:
    name = entry['Name']
    type_ = entry['Type']
    status = entry['Status']
    amount = entry['Amt']

    if name not in summary_data:
        summary_data[name] = {}

    if type_ not in summary_data[name]:
        summary_data[name][type_] = {'completed': 0, 'not completed': 0}

    if status == 'Completed':
        summary_data[name][type_]['completed'] += amount
    elif status == 'Not Completed':
        summary_data[name][type_]['not completed'] += amount

# Write the computed values to the Summary sheet
for row_idx, row in enumerate(data_rows, start=1):
    name = row[name_col].value
    if name not in summary_data:
        row[hd_col].value = 0
        row[sd_col].value = 0
    else:
        row[hd_col].value = summary_data[name].get('HD', {}).get('completed', 0) + summary_data[name].get('HD', {}).get('not completed', 0)
        row[sd_col].value = summary_data[name].get('SD', {}).get('completed', 0) + summary_data[name].get('SD', {}).get('not completed', 0)

# Save the workbook
wb.save('output.xlsx')
