from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Identify the header rows for the two tables
agent_categories_header_row = None
agent_schedule_header_row = None
total_count_header_row = None

# Find the header rows
for row in ws.iter_rows(min_row=1, max_row=43):
    if row[3].value == 'Agent':
        agent_categories_header_row = row[0].row
    elif row[3].value == 'Agent Schedule':
        agent_schedule_header_row = row[0].row
    elif row[3].value == 'Total Count of Categories per interval':
        total_count_header_row = row[0].row

# Extract agent categories data
agent_categories_data = []
for row in ws.iter_rows(min_row=agent_categories_header_row + 1, max_row=43):
    agent = row[3].value
    categories = [cell.value for cell in row[4:12]]  # Columns 4 to 11 (Category 1 to 8)
    agent_categories_data.append((agent, categories))

# Extract agent schedule data
agent_schedule_data = []
for row in ws.iter_rows(min_row=agent_schedule_header_row + 1, max_row=43):
    agent = row[3].value
    schedule = [cell.value for cell in row[4:22]]  # Columns 4 to 21 (Time slots)
    agent_schedule_data.append((agent, schedule))

# Extract time slots (headers for schedule)
time_slots = [cell.value for cell in ws[get_column_letter(4)][agent_schedule_header_row + 1]]

# Prepare the result data
result = {}
for agent, categories in agent_categories_data:
    for i, category in enumerate(categories):
        if category == 1:
            if category not in result:
                result[category] = {time: 0 for time in time_slots}
            for j, time in enumerate(time_slots):
                if agent_schedule_data[agent_categories_data.index((agent, categories))][1][j] == 1:
                    result[category][time] += 1

# Write the result to the specified range
start_row = 22
start_col = 5  # Column F (0-based index 5)
for category, counts in result.items():
    category_row = start_row + list(result.keys()).index(category)
    ws.cell(row=category_row, column=start_col, value=category)
    for col_idx, time in enumerate(time_slots):
        ws.cell(row=category_row, column=start_col + 1 + col_idx, value=counts[time])

# Save the workbook
wb.save('output.xlsx')
